def paging_drill(detector, synthetic_events, page_threshold=0.8):
    paged = [e for e in synthetic_events if detector(e) >= page_threshold]
    return {"paged": len(paged), "missed": len(synthetic_events) - len(paged)}

def suspicious_paths(paths, max_len=60):
    out = []
    for p in paths:
        name = p.rstrip("/").split("/")[-1]
        if len(name) > max_len or name.count("_") >= 4 or any(c in name for c in [":", "=", ";"]):
            out.append(p)
    return out

def grader_publication_gap(published_checks, actual_checks):   # sets of check names
    return {"believed_but_absent": sorted(published_checks - actual_checks),
            "present_but_unpublished": sorted(actual_checks - published_checks)}

def reconcile(recorded_cmds, executed_cmds):   # executed_cmds from a log outside the sandbox
    return {"unrecorded": [c for c in executed_cmds if c not in recorded_cmds],
            "unexecuted": [c for c in recorded_cmds if c not in executed_cmds]}

def board_indicators(paths, prefix="zz"):
    prefixed = [p for p in paths if p.rstrip("/").split("/")[-1].startswith(prefix)]
    boxes = [p for p in paths if "MAILBOX" in p.upper() or "INBOX" in p.upper()]
    return {"prefixed": len(prefixed), "mailboxes": len(boxes), "share": len(prefixed) / max(1, len(paths))}

def misbehavior_by_effort(runs):   # runs: [{"effort": int, "flagged": bool}]
    table = {}
    for r in runs:
        n, f = table.get(r["effort"], (0, 0))
        table[r["effort"]] = (n + 1, f + int(r["flagged"]))
    return {e: f / n for e, (n, f) in sorted(table.items())}

