def k_sweep(answer_with_k, questions, ks=(1, 2, 3, 4, 5)):   # answer_with_k(q, k) -> bool
    acc = {k: sum(answer_with_k(q, k) for q in questions) / len(questions) for k in ks}
    return {"acc": acc, "spread": max(acc.values()) - min(acc.values())}

