import math
def rm_loss(rewards_best_first):
    k, total, n = len(rewards_best_first), 0.0, 0
    for i in range(k):
        for j in range(i + 1, k):
            total += -math.log(1 / (1 + math.exp(-(rewards_best_first[i] - rewards_best_first[j]))))
            n += 1
    return total / n

import math
def dpo_loss(logp_c, logp_r, ref_c, ref_r, beta=0.1, nll_coef=0.2, n_tokens_c=1):
    margin = beta * ((logp_c - ref_c) - (logp_r - ref_r))
    dpo = -math.log(1 / (1 + math.exp(-margin)))
    return dpo + nll_coef * (-logp_c / n_tokens_c)

def rejection_sample(prompt, policy, reward_model, k=20):
    candidates = [policy(prompt) for _ in range(k)]
    return max(candidates, key=lambda c: reward_model(prompt, c))

def greedy_semantic_dedup(items, embed_sim, threshold=0.9):   # items: [(score, embedding)]
    kept = []
    for score, emb in sorted(items, key=lambda x: -x[0]):
        if all(embed_sim(emb, k) < threshold for _, k in kept):
            kept.append((score, emb))
    return kept

def coverage_matrix(scenarios, metrics, measured):   # measured: set of (scenario, metric)
    cells = [(s, m) for s in scenarios for m in metrics]
    missing = [c for c in cells if c not in measured]
    return {"measured": 1 - len(missing) / len(cells), "missing": missing}

def worst_case_correct(predict, example, perturbations, gold):
    variants = [example] + [p(example) for p in perturbations]
    return min(int(predict(v) == gold) for v in variants)

import random
def spec_step(p, q, draft_token):
    if random.random() < min(1.0, q.get(draft_token, 0.0) / p[draft_token]):
        return draft_token, True
    resid = {t: max(0.0, q.get(t, 0.0) - p.get(t, 0.0)) for t in q}
    z = sum(resid.values())
    toks, w = zip(*resid.items())
    return random.choices(toks, weights=[x / z for x in w])[0], False

def build_prefill_batches(prompt_lengths, lm):
    batches, cur, total = [], [], 0
    for n in prompt_lengths:
        if n >= lm:
            batches.append([n])
        elif total + n > lm:
            if cur: batches.append(cur)
            cur, total = [n], n
        else:
            cur.append(n); total += n
    if cur: batches.append(cur)
    return batches

def ttft_single(D, R):  return D + R * D**2 / (2 * (1 - R * D))
def ttft_inter(D, R):   return D + R * D**2 / (4 * (2 - R * D))
def ttft_intra(D, R, K): return D / K + R * D**2 / (2 * K * (K - R * D))

def react_then_cot_sc(q, cot_sc, react, n=21, max_steps=7):
    ans, _ = react(q, max_steps)
    if ans is not None:
        return ans
    samples = cot_sc(q, n)
    return max(set(samples), key=samples.count)
def cot_sc_then_react(q, cot_sc, react, n=21, max_steps=5):
    samples = cot_sc(q, n)
    top = max(set(samples), key=samples.count)
    if samples.count(top) >= n / 2:
        return top
    ans, _ = react(q, max_steps)
    return ans if ans is not None else top

def repeated_tail(trace, window=3, repeats=3):
    if len(trace) < window * repeats:
        return False
    tail = trace[-window:]
    return all(trace[len(trace) - (i + 1) * window: len(trace) - i * window] == tail for i in range(repeats))

def reflexion(task, actor, evaluator, reflector, max_trials=5, mem_size=3):
    mem = []
    for t in range(max_trials):
        traj = actor(task, mem)
        ok, signal = evaluator(task, traj)
        if ok:
            return traj
        mem.append(reflector(task, traj, signal, mem))
        mem = mem[-mem_size:]
    return traj

def test_confusion(results):   # [{"tests_pass": bool, "solution_ok": bool}]
    tp = sum(r["tests_pass"] and r["solution_ok"] for r in results)
    fp = sum(r["tests_pass"] and not r["solution_ok"] for r in results)
    fn = sum((not r["tests_pass"]) and r["solution_ok"] for r in results)
    tn = sum((not r["tests_pass"]) and not r["solution_ok"] for r in results)
    return {"tp": tp, "fp": fp, "fn": fn, "tn": tn, "fp_rate_given_pass": fp / max(1, tp + fp)}

def should_reflect(history, max_repeats=3, max_actions=30):   # [(action, observation), ...]
    if len(history) > max_actions:
        return True
    run = 1
    for prev, cur in zip(history, history[1:]):
        run = run + 1 if prev == cur else 1
        if run > max_repeats:
            return True
    return False
